cd /workspace/tmp/tests && python3 - <<'EOF'
import random, sys, collections
sys.path[:0]=['/workspace/tmp/tests','/opt/emicro-deps','/workspace/project']
from ebpf.create_dfa import create, registry_columns
from brute import brute_image
names=['A','B','C']
reg=[{'name':n,'label':i+1} for i,n in enumerate(names)]
cols,colmap=registry_columns(reg)
rng=random.Random(1)
ops=['startswith','endswith','contains']
pool=[(rng.choice(ops), tuple(rng.choice(names) for _ in range(rng.randint(0,4)))) for _ in range(4)]
def gen(rng):
    def path(maxlen): return ','.join(rng.choice(names) for _ in range(rng.randint(0,maxlen)))
    def pred(d):
        if d>=rng.randint(1,4) or rng.random()<0.4:
            if rng.random()<0.55: return 'match(%s)'%path(4)
            op,p=rng.choice(pool); return '%s(%s)'%(op,','.join(p))
        if rng.random()<0.25: return 'not(%s)'%pred(d+1)
        return '(%s %s %s)'%(pred(d+1),rng.choice(['and','or']),pred(d+1))
    return ' '.join('%s %s;'%(pred(0),rng.choice(['allow','allow','drop'])) for _ in range(rng.randint(0,4)))
reasons=collections.Counter()
for i in range(250):
    p=gen(rng)
    try: create(p,cols,colmap)
    except Exception as e: reasons['mine %s:%s'%(type(e).__name__,e)]+=1; continue
    try: brute_image(p,cols,colmap,5,5)
    except Exception as e: reasons['brute %s:%s'%(type(e).__name__,str(e)[:40])]+=1
for k,v in reasons.most_common(8): print(v,k)
EOF
